CREATE SEQUENCE course_id_seq START WITH 1 INCREMENT BY 1;
CREATE TABLE courses (id BIGINT DEFAULT nextval('course_id_seq') PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, price NUMERIC(12,2) NOT NULL, sessions INTEGER NOT NULL, bonus_sessions INTEGER NOT NULL DEFAULT 0, validity_days INTEGER NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE SEQUENCE payment_method_id_seq START WITH 1 INCREMENT BY 1;
CREATE TABLE payment_methods (id BIGINT DEFAULT nextval('payment_method_id_seq') PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO payment_methods(code,name) SELECT 'CASH','Cash' WHERE NOT EXISTS (SELECT 1 FROM payment_methods WHERE code='CASH');
INSERT INTO payment_methods(code,name) SELECT 'TRANSFER','Transfer' WHERE NOT EXISTS (SELECT 1 FROM payment_methods WHERE code='TRANSFER');
INSERT INTO payment_methods(code,name) SELECT 'QR','QR' WHERE NOT EXISTS (SELECT 1 FROM payment_methods WHERE code='QR');
INSERT INTO payment_methods(code,name) SELECT 'CARD','Credit Card' WHERE NOT EXISTS (SELECT 1 FROM payment_methods WHERE code='CARD');
